import { describe, expect, it } from "vitest";
import {
  SELECTORS,
  encodeApprove,
  encodeBorrow,
  encodeRepayAssets,
  encodeRepayShares,
  encodeSupplyCollateral,
  encodeWithdrawCollateral,
} from "@/lib/lista/calldata";

// Expected values generated once with foundry `cast calldata`, where
//   P='(0x8d0D000Ee44948FC98c9B98A4FA4921476f08B0d,0x02Fca66C1D1aFB4E2A7884261eB00F63598a7436,0x526D09c604A17D98cb1f260a7774A239990dbDfb,0xFe7dAe87Ebb11a7BEB9F534BB23267992d9cDe7c,750000000000000000)'
//   T='(address,address,address,address,uint256)'
//   U=0x1111111111111111111111111111111111111111  R=0x2222222222222222222222222222222222222222
//   approve:     cast calldata "approve(address,uint256)" 0x8F73b65B4caAf64FBA2aF91cC5D4a2A1318E5D8C 1000000000000000000
//   supply:      cast calldata "supplyCollateral($T,uint256,address,bytes)" "$P" 2500000000000000000 $U 0x
//   borrow:      cast calldata "borrow($T,uint256,uint256,address,address)" "$P" 100000000000000000000 0 $U $R
//   repayAssets: cast calldata "repay($T,uint256,uint256,address,bytes)" "$P" 100000000000000000000 0 $U 0x
//   repayShares: cast calldata "repay($T,uint256,uint256,address,bytes)" "$P" 0 98765432109876543210 $U 0x
//   withdraw:    cast calldata "withdrawCollateral($T,uint256,address,address)" "$P" 2500000000000000000 $U $R
const params = {
  loanToken: "0x8d0D000Ee44948FC98c9B98A4FA4921476f08B0d",
  collateralToken: "0x02Fca66C1D1aFB4E2A7884261eB00F63598a7436",
  oracle: "0x526D09c604A17D98cb1f260a7774A239990dbDfb",
  irm: "0xFe7dAe87Ebb11a7BEB9F534BB23267992d9cDe7c",
  lltv: 750000000000000000n,
} as const;
const moolah = "0x8F73b65B4caAf64FBA2aF91cC5D4a2A1318E5D8C";
const user = "0x1111111111111111111111111111111111111111";
const receiver = "0x2222222222222222222222222222222222222222";

const EXPECTED = {
  approve: "0x095ea7b30000000000000000000000008f73b65b4caaf64fba2af91cc5d4a2a1318e5d8c0000000000000000000000000000000000000000000000000de0b6b3a7640000",
  supply: "",
  borrow: "",
  repayAssets: "",
  repayShares: "",
  withdraw: "",
};

describe("Moolah calldata", () => {
  it("encodes approve", () => {
    expect(encodeApprove(moolah, 10n ** 18n)).toBe(EXPECTED.approve);
  });
  it("encodes supplyCollateral", () => {
    expect(encodeSupplyCollateral(params, 25n * 10n ** 17n, user)).toBe(EXPECTED.supply);
  });
  it("encodes borrow", () => {
    expect(encodeBorrow(params, 100n * 10n ** 18n, user, receiver)).toBe(EXPECTED.borrow);
  });
  it("encodes repay by assets", () => {
    expect(encodeRepayAssets(params, 100n * 10n ** 18n, user)).toBe(EXPECTED.repayAssets);
  });
  it("encodes repay by shares", () => {
    expect(encodeRepayShares(params, 98765432109876543210n, user)).toBe(EXPECTED.repayShares);
  });
  it("encodes withdrawCollateral", () => {
    expect(encodeWithdrawCollateral(params, 25n * 10n ** 17n, user, receiver)).toBe(EXPECTED.withdraw);
  });
  it("exports selectors matching the encoded calldata", () => {
    expect(EXPECTED.approve.startsWith(SELECTORS.approve)).toBe(true);
    expect(EXPECTED.supply.startsWith(SELECTORS.supplyCollateral)).toBe(true);
    expect(EXPECTED.borrow.startsWith(SELECTORS.borrow)).toBe(true);
    expect(EXPECTED.repayAssets.startsWith(SELECTORS.repay)).toBe(true);
    expect(EXPECTED.repayShares.startsWith(SELECTORS.repay)).toBe(true);
    expect(EXPECTED.withdraw.startsWith(SELECTORS.withdrawCollateral)).toBe(true);
    expect(SELECTORS).toEqual({
      approve: "0x095ea7b3",
      supplyCollateral: "0x238d6579",
      borrow: "0x50d8cd4b",
      repay: "0x20b76e81",
      withdrawCollateral: "0x8720316d",
    });
  });
});
